#!/usr/bin/env python3
"""FS3 v211 - FreeSpace target marks, tempo, capital ship lanes (Silvio, 10.10.2026).

    Marks      The target as FreeSpace draws it (hudbrackets.cpp): four
               fading corners a quarter of the box long, at least 30 px at
               1024, the distance as a number under the lower right corner,
               the FS2 lead indicator (four small triangles), the aspect
               lock ring travelling from the nose to the target and spinning
               round it with LOCKED - all in her side colour, with a dark
               edge so they hold against fire and beams. Other hostile
               fighters and bombers: small, paler FS brackets instead of the
               red chevron (yellow and blinking on a run at one of our
               capital ships, as before).
    Tempo      About twice the v210 pace (TEMPO_K = 2): small craft, every
               round, their reach. Speeds in the FS ratio: every small craft
               after its $Max Velocity (Myrmidon 75 m/s = 3.4 per step), the
               AI as fast as the player in the same hull, AI bolts as fast
               as the same gun on the player, AI missiles with the FS2 speed
               and life of the round they stand for.
    Capitals   No more drifting up and down. Warships (and allied
               freighters) drive along their own lane towards the other side
               at their FS speed and turn round - before the edge, before
               anything standing in their lane - then back to their station.
               The model yaws through the turn; outline, hits and mounts
               follow. Lanes are kept apart; a ship with no free lane, or
               held by her task in the mission, stands. Bosses hold station.

Needs v210. Edits src/10_core.js, 20_render.js, 30_waves.js, 40_world.js,
50_combat.js, 55_arms.js, 57_turrets.js, 59_field3d.js, 60_effects.js,
70_ui.js, 72_target.js and the tests shipsim.js, fieldsim.js. No new files.
Run assemble.py 211 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/72_target.js"):
    sys.exit("Abbruch: erst v210 einspielen.")
_c = open("src/10_core.js", encoding="utf-8").read()
if "const TEMPO_K = 2;" in _c:
    sys.exit("v211 ist schon eingespielt.")
if "const TEMPO_K = 1;" not in _c:
    sys.exit("Abbruch: erst v210 einspielen.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
